// answer-frequency corpus (crossword-clue TEXT was intentionally NOT reused —
// only the underlying word list — to avoid any copyright concern with
// published clue wording). Grids were constructed with a constraint-propagation
// backtracking solver. All clues are original, written for this app.
//
// Daily selection uses a seeded shuffle over this array's indices (see
// crosswordGame.tsx's getDailyIndex/buildDailyOrder), the same pattern Wordle
// uses, so puzzle order here has no bearing on which puzzle appears on which day.

export type CrosswordDirection = "A" | "D";

export interface CrosswordSlot {
  dir: CrosswordDirection;
  row: number;
  col: number;
  answer: string;
  clue: string;
}

export interface CrosswordPuzzle {
  black: number[][];
  slots: CrosswordSlot[];
}

